38	// Split a transcript into { raw, entry } pairs, preserving the original line
39	// bytes — the capture must stay byte-faithful (re-encoding could reorder or
40	// reformat), so raw is what gets written and entry is only read for slicing.
41	// (engine/checks/helpers/session-transcript.mjs parseEntries returns parsed objects only, which is
42	// right for conversation rules but loses the fidelity capture needs.)
43	export function parseLines(text) {
44	  const out = [];
45	  for (const raw of (text || '').split('\n')) {
46	    if (!raw.trim()) continue;
47	    try { out.push({ raw, entry: JSON.parse(raw) }); } catch { /* partial trailing write — skip */ }
48	  }
49	  return out;
50	}
