54	// predecessor's timestamp so it stays glued to its neighbors through the merge.
55	export function bundleStreams(streams) {
56	  const tagged = [];
57	  streams.forEach((lines, s) => {
58	    let carry = '';
59	    lines.forEach((line, i) => {
60	      if (typeof line.entry.timestamp === 'string') carry = line.entry.timestamp;
61	      tagged.push({ raw: line.raw, entry: line.entry, ts: carry, s, i });
62	    });
63	  });
