67	}
68	
69	// Entries strictly after `lastTs` (ISO strings compare lexicographically) — the
70	// delta a twice-merging session captures. null lastTs = no prior capture = all.
71	export function sliceAfter(bundled, lastTs) {
72	  if (!lastTs) return bundled;
73	  return bundled.filter((l) => l.ts > lastTs);
74	}
75	
76	export function maxTimestamp(bundled) {
77	  let max = null;
78	  for (const l of bundled) if (l.ts && (!max || l.ts > max)) max = l.ts;
79	  return max;
