90	const STRUCTURAL_ENV = new Set([
91	  'PATH', 'HOME', 'PWD', 'OLDPWD', 'SHELL', 'SHLVL', 'TERM', 'COLORTERM', '_',
92	  'LANG', 'LANGUAGE', 'USER', 'LOGNAME', 'HOSTNAME', 'HOSTTYPE', 'OSTYPE', 'MACHTYPE',
93	  'TMPDIR', 'TMP', 'TEMP', 'EDITOR', 'VISUAL', 'PAGER', 'DISPLAY', 'NODE_ENV', 'CI',
94	  'CLAUDE_PROJECT_DIR', 'CLAUDE_CODE_SESSION_ID', 'PLAYWRIGHT_BROWSERS_PATH',
95	  'GITHUB_REPOSITORY', 'GITHUB_REF', 'GITHUB_REF_NAME', 'GITHUB_SHA', 'GITHUB_WORKSPACE',
96	  'GITHUB_EVENT_NAME', 'GITHUB_RUN_ID', 'GITHUB_RUN_NUMBER', 'GITHUB_JOB', 'GITHUB_ACTOR',
97	  'RUNNER_OS', 'RUNNER_ARCH', 'RUNNER_TEMP', 'RUNNER_TOOL_CACHE',
